public static Queue<Integer> merge(Queue<Integer> q1, Queue<Integer> q2) {
    Queue<Integer> result = new Queue<Integer>();
    while (!q1.isEmpty() && !q2.isEmpty()) {
        if (q1.head() <= q2.head()) {
            result.insert(q1.remove());
        } else {
            result.insert(q2.remove());
        }
    }
    while (!q1.isEmpty()) {
        result.insert(q1.remove());
    }
    while (!q2.isEmpty()) {
        result.insert(q2.remove());
    }
    return result;
}

public static boolean isSorted(Queue<Integer> q) {
    Queue<Integer> temp = new Queue<Integer>();
    boolean sorted = true;
    while (!q.isEmpty()) {
        int x = q.remove();
        if (!q.isEmpty() && x > q.head()) {
            sorted = false;
        }
        temp.insert(x);
    }
    while (!temp.isEmpty()) {
        q.insert(temp.remove());
    }
    return sorted;
}

