public static Queue<int> Merge(Queue<int> q1, Queue<int> q2)
{
    Queue<int> result = new Queue<int>();
    while (!q1.IsEmpty() && !q2.IsEmpty())
    {
        if (q1.Head() <= q2.Head())
        {
            result.Insert(q1.Remove());
        }
        else
        {
            result.Insert(q2.Remove());
        }
    }
    while (!q1.IsEmpty())
    {
        result.Insert(q1.Remove());
    }
    while (!q2.IsEmpty())
    {
        result.Insert(q2.Remove());
    }
    return result;
}

public static bool IsSorted(Queue<int> q)
{
    Queue<int> temp = new Queue<int>();
    bool sorted = true;
    while (!q.IsEmpty())
    {
        int x = q.Remove();
        if (!q.IsEmpty() && x > q.Head())
        {
            sorted = false;
        }
        temp.Insert(x);
    }
    while (!temp.IsEmpty())
    {
        q.Insert(temp.Remove());
    }
    return sorted;
}

